import '../core/identity.dart';
enum ClaimVerification{exact,entailed,partial,contradicted,unsupported,unknown}
class ClaimCandidate{final String claimId,text;final List<String> evidenceIds;const ClaimCandidate({required this.claimId,required this.text,this.evidenceIds=const[]});}
class ClaimEvidence{final String id,text;final String? truthStatus;const ClaimEvidence({required this.id,required this.text,this.truthStatus});}
class ClaimVerificationResult{final String claimId,detail;final ClaimVerification verification;final double confidence;final List<String> evidenceIds;const ClaimVerificationResult({required this.claimId,required this.verification,required this.confidence,required this.evidenceIds,required this.detail});}
List<ClaimCandidate>decomposeClaims(String answer){final chunks=answer.split(RegExp(r'(?<=[.!?])\s+|\n+')).map(normalizeText).where((e)=>e.length>=4).toList();return List.generate(chunks.length,(i)=>ClaimCandidate(claimId:'claim_${(i+1).toString().padLeft(3,'0')}',text:chunks[i]));}
double _overlap(String a,String b){final aa=RegExp(r"[a-z0-9][a-z0-9'-]{2,}",caseSensitive:false).allMatches(a.toLowerCase()).map((m)=>m.group(0)!).toSet();final bb=RegExp(r"[a-z0-9][a-z0-9'-]{2,}",caseSensitive:false).allMatches(b.toLowerCase()).map((m)=>m.group(0)!).toSet();if(aa.isEmpty||bb.isEmpty)return 0;return aa.intersection(bb).length/[aa.length,bb.length].reduce((a,b)=>a>b?a:b);}
List<ClaimVerificationResult>verifyClaimsDeterministically({required List<ClaimCandidate>claims,required List<ClaimEvidence>evidence}){final byId={for(final e in evidence)e.id:e};final out=<ClaimVerificationResult>[];for(final claim in claims){final bounded=claim.evidenceIds.isEmpty?evidence:claim.evidenceIds.map((id)=>byId[id]).whereType<ClaimEvidence>().toList();if(bounded.isEmpty){out.add(ClaimVerificationResult(claimId:claim.claimId,verification:ClaimVerification.unsupported,confidence:1,evidenceIds:const[],detail:'No evidence was supplied for this claim.'));continue;}ClaimEvidence? exact;for(final e in bounded){final c=normalizeText(claim.text).toLowerCase(),t=normalizeText(e.text).toLowerCase();if(c.isNotEmpty&&(t==c||t.contains(c))){exact=e;break;}}if(exact!=null){out.add(ClaimVerificationResult(claimId:claim.claimId,verification:ClaimVerification.exact,confidence:1,evidenceIds:[exact.id],detail:'Claim text is directly contained in bounded evidence.'));continue;}final scored=bounded.map((e)=>MapEntry(e,_overlap(claim.text,e.text))).toList()..sort((a,b)=>b.value.compareTo(a.value));final best=scored.first;out.add(ClaimVerificationResult(claimId:claim.claimId,verification:best.value>=.35?ClaimVerification.unknown:ClaimVerification.unsupported,confidence:best.value,evidenceIds:best.value>0?[best.key.id]:const[],detail:best.value>=.35?'Evidence is related but semantic entailment still requires an independent judge.':'No bounded evidence provides sufficient direct support.'));}return out;}
